INSERT INTO movimientos_inventario (sucursal_id, producto_id, talla_id, color_id, tipo, cantidad, referencia_tipo, observaciones)
       SELECT (SELECT id FROM sucursales WHERE nombre = 'MISSI Cochabamba'), (SELECT id FROM productos WHERE nombre = 'Palazzo sastrero'), (SELECT id FROM tallas WHERE nombre = 'M'), (SELECT id FROM colores WHERE nombre = 'Guindo'), 'entrada', 3, 'importacion_supabase', 'stock inicial importado'
        WHERE 3 > 0 AND NOT EXISTS (SELECT 1 FROM movimientos_inventario WHERE referencia_tipo = 'importacion_supabase'
